import{_ as o,c as d,o as l,b0 as c}from"./chunks/framework.BWMBvyU7.js";const _=JSON.parse('{"title":"LV035-多路复用IO-04-总结","description":null,"frontmatter":{"title":"LV035-多路复用IO-04-总结","date":"2026-03-16T14:16:36.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/net/net-programming/126d38f2584411037236e5d8","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-03-16T14:16:36.272Z","fulluuid":"37236e5d89874620a1eaf0daa85c4641","useduuid":"37236e5d8"}},"headers":[],"relativePath":"sdoc/net/net-programming/126d38f2584411037236e5d8.md","filePath":"sdoc/04-网络相关/20-网络编程/LV035-多路复用IO-04-总结.md","lastUpdated":1773672539000}'),t={name:"sdoc/net/net-programming/126d38f2584411037236e5d8.md"};function a(p,e,r,s,n,i){return l(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="lv035-多路复用io-04-总结" tabindex="-1">LV035-多路复用IO-04-总结 <a class="header-anchor" href="#lv035-多路复用io-04-总结" aria-label="Permalink to &quot;LV035-多路复用IO-04-总结&quot;">​</a></h1><p>本文主要是网络编程——多路复用IO中的select、poll和epoll的总结的相关笔记，若笔记中有错误或者不合适的地方，欢迎批评指正😃。</p><h2 id="一、select、poll和epoll对比" tabindex="-1">一、<code>select</code>、<code>poll</code>和<code>epoll</code>对比 <a class="header-anchor" href="#一、select、poll和epoll对比" aria-label="Permalink to &quot;一、`select`、`poll`和`epoll`对比&quot;">​</a></h2><h3 id="_1-用户态将文件描述符传入内核的方式" tabindex="-1">1. 用户态将文件描述符传入内核的方式 <a class="header-anchor" href="#_1-用户态将文件描述符传入内核的方式" aria-label="Permalink to &quot;1. 用户态将文件描述符传入内核的方式&quot;">​</a></h3><ul><li><p><code>select</code>：创建<code>3</code>个文件描述符集并拷贝到内核中，分别监听读、写、异常动作。这里受到单个进程可以打开的<code>fd</code>数量限制，由<code>FD_SETSIZE</code>设置，默认是最大是<code>1024</code>。</p></li><li><p><code>poll</code>：将传入的<code>struct pollfd</code>结构体数组拷贝到内核中进行监听，<code>poll</code>克服了<code>select</code>模型的最大并发数限制。</p></li><li><p><code>epoll</code>：执行<code>epoll_create</code>，会在<strong>内核</strong>的高速<code>cache</code>区中，建立一颗红黑树以及就绪链表(该链表存储已经就绪的文件描述符)。接着用户执行的<code>epoll_ctl</code>函数，添加文件描述符会在红黑树上增加相应的结点。</p></li></ul><h3 id="_2-内核态检测文件描述符读写状态的方式" tabindex="-1">2. 内核态检测文件描述符读写状态的方式 <a class="header-anchor" href="#_2-内核态检测文件描述符读写状态的方式" aria-label="Permalink to &quot;2. 内核态检测文件描述符读写状态的方式&quot;">​</a></h3><ul><li><p><code>select</code>：采用<strong>轮询</strong>方式，遍历所有<code>fd</code>，最后返回一个描述符读写操作是否就绪的<code>mask</code>掩码，根据这个掩码给<code>fd_set</code>赋值。</p></li><li><p><code>poll</code>：同样采用<strong>轮询</strong>方式，查询每个<code>fd</code>的状态，如果就绪则在等待队列中加入一项并继续遍历。</p></li><li><p><code>epoll</code>：采用<strong>事件回调</strong>机制。在执行 <code>epoll_ctl</code> 的<code>add</code>操作时，不仅将文件描述符放到红黑树上，而且也注册了回调函数；内核在检测到某文件描述符可读/可写时会调用回调函数，该回调函数将文件描述符放在就绪链表中。</p></li></ul><h3 id="_3-找到就绪的文件描述符并传递给用户态的方式" tabindex="-1">3. 找到就绪的文件描述符并传递给用户态的方式 <a class="header-anchor" href="#_3-找到就绪的文件描述符并传递给用户态的方式" aria-label="Permalink to &quot;3. 找到就绪的文件描述符并传递给用户态的方式&quot;">​</a></h3><ul><li><p><code>select</code>：将之前传入的<code>fd_set</code>拷贝传出到<strong>用户态</strong>并返回就绪的文件描述符总数。用户态并不知道是哪些文件描述符处于就绪态，需要遍历来判断。</p></li><li><p><code>poll</code>：将之前传入的 <code>fd</code> 数组拷贝传出<strong>用户态</strong>，并返回就绪的文件描述符总数。用户态并不知道是哪些文件描述符处于就绪态，需要遍历来判断。</p></li><li><p><code>epoll</code>：<code>epoll_wait</code> 只用观察<strong>就绪链表</strong>中有无数据即可，最后将链表的数据返回给数组, 并返回就绪的数量。<strong>内核</strong>，将就绪的文件描述符，放在传入的数组中。然后，依次遍历，处理即可。这里返回的文件描述符，是通过 <code>mmap()</code> ，让内核和用户空间，共享同一块内存实现传递的，减少了不必要的拷贝。</p></li></ul><h3 id="_4-重复监听的处理方式" tabindex="-1">4. 重复监听的处理方式 <a class="header-anchor" href="#_4-重复监听的处理方式" aria-label="Permalink to &quot;4. 重复监听的处理方式&quot;">​</a></h3><ul><li><p><code>select</code>：将新的监听文件描述符集合拷贝传入内核中，继续上边的步骤。</p></li><li><p><code>poll</code>：将新的<code>struct pollfd</code>结构体数组拷贝传入内核中，继续上边的步骤。</p></li><li><p><code>epoll</code>：无需重新构建红黑树，直接沿用已存在的即可。</p></li></ul><h3 id="_5-时间复杂度" tabindex="-1">5. 时间复杂度 <a class="header-anchor" href="#_5-时间复杂度" aria-label="Permalink to &quot;5. 时间复杂度&quot;">​</a></h3><ul><li><p><code>select</code>：<code>O(n)</code> ，随着连接数<code>n</code>的增大而增大。</p></li><li><p><code>poll</code>：<code>O(n)</code> ，随着连接数<code>n</code>的增大而增大。</p></li><li><p><code>epoll</code>：<code>O(1)</code> ，<strong>不会</strong>随着连接数<code>n</code>的增大而增大。</p></li></ul><h2 id="二、epoll更高效" tabindex="-1">二、<code>epoll</code>更高效？ <a class="header-anchor" href="#二、epoll更高效" aria-label="Permalink to &quot;二、`epoll`更高效？&quot;">​</a></h2><p><code>select</code>和<code>poll</code>的动作基本一致，只是<code>poll</code>采用链表来进行文件描述符的存储，而<code>select</code>采用<code>fd</code>标注位来存放，所以<code>select</code>会受到最大连接数的限制，而<code>poll</code>不会。</p><p><code>select</code>、<code>poll</code>、<code>epoll</code>虽然都会返回就绪的文件描述符数量, 但是<code>select</code>和<code>poll</code>并不会明确指出是哪些文件描述符就绪，而<code>epoll</code>会。这就意味着系统调用返回后，调用<code>select</code>和<code>poll</code>的程序需要遍历监听的整个文件描述符找到是哪个文件描述符处于就绪，而<code>epoll</code>则直接处理即可（直接监听到了哪些文件描述符就绪）。</p><p><code>select</code>、<code>poll</code>都需要将有关文件描述符的数据结构拷贝进内核，最后再拷贝出来。而<code>epoll</code>创建的有关文件描述符的数据结构本身就存于内核态中，系统调用返回时利用 <code>mmap()</code> 文件映射内存加速与内核空间的消息传递：即<code> epoll</code> 使用 <code>mmap()</code> 减少复制开销。</p><p><code>select</code>、<code>poll</code>采用 <strong>轮询</strong> 的方式来检查文件描述符是否处于就绪态，而<code>epoll</code>采用回调机制。造成的结果就是，随着<code>fd</code>的增加，<code>select</code>和<code>poll</code>的效率会线性降低，而<code>epoll</code>不会受到太大影响，除非活跃的<code>socket</code>很多。</p><p><code>epoll</code>的边缘触发模式效率高，系统不会充斥大量不关心的就绪文件描述符。</p><p>最后，虽然<code>epoll</code>的性能最好，但是在<strong>连接数少并且连接都十分活跃</strong>的情况下，<code>select</code>和<code>poll</code>的性能可能比<code>epoll</code>好，毕竟<code>epoll</code>的通知机制需要很多函数回调。</p>',20)])])}const h=o(t,[["render",a]]);export{_ as __pageData,h as default};
